"""Read-only summary of node channel records and state."""
import argparse
from collections import Counter
import json
from pathlib import Path
import re
import stat


def strict_json(data):
    def reject(value):
        raise ValueError(value)

    return json.loads(data, parse_constant=reject)


def regular(path):
    try:
        return stat.S_ISREG(path.lstat().st_mode)
    except FileNotFoundError:
        return False


def channel_files(folder, channel):
    pattern = re.compile(re.escape(channel) + r"\.(\d{12})\.jsonl\Z")
    files = []
    for path in folder.iterdir():
        match = pattern.fullmatch(path.name)
        if match and regular(path):
            files.append((int(match.group(1)), path))
    result = [path for _, path in sorted(files)]
    active = folder / (channel + ".active.jsonl")
    if regular(active):
        result.append(active)
    return result


def read_channel(folder, channel, bad):
    counts = Counter()
    for path in channel_files(folder, channel):
        parts = path.read_bytes().split(b"\n")
        for line_number, raw in enumerate(parts[:-1], 1):
            try:
                value = strict_json(raw)
            except (ValueError, UnicodeError):
                bad.append({"file": path.name, "line": line_number, "why": "bad_json"})
                continue
            seq = value.get("seq") if isinstance(value, dict) else None
            if type(seq) is not int or seq < 1:
                bad.append({"file": path.name, "line": line_number, "why": "no_seq"})
            else:
                counts[seq] += 1
        if parts[-1]:
            bad.append({"file": path.name, "line": len(parts), "why": "torn"})
    seqs = sorted(counts)
    missing = [[left + 1, right - 1] for left, right in zip(seqs, seqs[1:]) if right > left + 1]
    return {"count": sum(counts.values()), "first": seqs[0] if seqs else None,
            "last": seqs[-1] if seqs else None, "missing": missing,
            "dup": [seq for seq in seqs if counts[seq] >= 2],
            "next_seq": None, "unacked": None, "stale_next": None}, seqs


def read_state(folder):
    path = folder / "state.json"
    try:
        mode = path.lstat().st_mode
    except FileNotFoundError:
        return None, False
    try:
        if not stat.S_ISREG(mode):
            raise ValueError("state is not a regular file")
        value = strict_json(path.read_bytes())
        if not isinstance(value, dict) or not isinstance(value.get("channels"), dict):
            raise ValueError("invalid state structure")
    except (OSError, ValueError, UnicodeError):
        return None, True
    return value["channels"], False


def summarize(folder):
    bad = []
    channels = {}
    sequences = {}
    for name in ("obs", "must"):
        channels[name], sequences[name] = read_channel(folder, name, bad)
    state, bad_state = read_state(folder)
    if state is not None:
        for name in ("obs", "must"):
            entry = state.get(name)
            if (not isinstance(entry, dict) or type(entry.get("next_seq")) is not int
                    or (name == "must" and type(entry.get("acked_upto")) is not int)):
                bad_state = True
                continue
            result = channels[name]
            result["next_seq"] = entry["next_seq"]
            if name == "must":
                result["unacked"] = sum(seq > entry["acked_upto"] for seq in sequences[name])
            if result["last"] is not None:
                result["stale_next"] = entry["next_seq"] != result["last"] + 1
    if bad_state:
        bad.append({"file": "state.json", "line": None, "why": "bad_state"})
    bad.sort(key=lambda item: (item["file"], item["line"] if item["line"] is not None else 0, item["why"]))
    return {"v": 1, "channels": channels, "bad": bad}


def main(argv=None):
    parser = argparse.ArgumentParser(description="Summarize node sequence gaps without writes")
    parser.add_argument("folder", type=Path)
    args = parser.parse_args(argv)
    if not args.folder.is_dir():
        parser.error("folder is not a directory")
    print(json.dumps(summarize(args.folder), separators=(",", ":")))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
